# WReparse - path semantics
# Canonicalisation, directory-boundary containment, and link-target resolution.
# Part of the WReparse implementation. See the contract under docs/
#
# Only Get-WReparseCanonicalPath, Test-WReparseWithinRoot and
# Resolve-WReparseLinkTarget belong to the public surface; the remaining helpers
# in this file are internal.

$script:WReparseVolumeSeparator = [char]92   # '\'
$script:WReparseAltSeparator = [char]47      # '/'

# Canonical form used for every comparison and for the report (contract 5.1):
#   * full (rooted) path with '.' and '..' collapsed
#   * no trailing directory separator, except for a volume root ('C:\')
#     or a UNC share root ('\\server\share'), which keep their shape
#   * original casing preserved
function Get-WReparseCanonicalPath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$Path
    )

    if ($null -eq $Path) {
        throw (New-Object System.ArgumentException('Path is null.', 'Path'))
    }
    $candidate = $Path
    if ($candidate.Length -eq 0) {
        throw (New-Object System.ArgumentException('Path is empty.', 'Path'))
    }

    # NT native / Win32 device forms are folded onto the plain Win32 form so
    # that containment checks and comparisons stay consistent.
    if ($candidate.StartsWith('\\?\') -or $candidate.StartsWith('\??\')) {
        $candidate = $candidate.Substring(4)
        if ($candidate.StartsWith('UNC\', [System.StringComparison]::OrdinalIgnoreCase)) {
            $candidate = '\' + $candidate.Substring(4)
        }
    }
    if ($candidate.Length -eq 0) {
        throw (New-Object System.ArgumentException('Path is empty.', 'Path'))
    }

    # Throws for strings that are not a legal path; callers translate that into
    # the contract's invalid_argument error code.
    $full = [System.IO.Path]::GetFullPath($candidate)
    if ([string]::IsNullOrEmpty($full)) {
        throw (New-Object System.ArgumentException('Path could not be canonicalised.', 'Path'))
    }

    $trimmed = $full.TrimEnd($script:WReparseVolumeSeparator, $script:WReparseAltSeparator)
    if ($trimmed.Length -eq 0) {
        # Root of the current volume ('\' or '/'): keep the separator.
        return $full
    }
    if ($trimmed.StartsWith('\\')) {
        # UNC: '\\server\share' is the share root and keeps its shape.
        return $trimmed
    }
    if (($trimmed.Length -eq 2) -and ($trimmed[1] -eq ':')) {
        # Volume root: 'C:' is not the same location as 'C:\', keep 'C:\'.
        return $trimmed + '\'
    }
    return $trimmed
}

# Directory-boundary aware containment (contract 5.2). 'C:\root2' is NOT inside
# 'C:\root' even though 'C:\root2'.StartsWith('C:\root') is true. Windows path
# comparison is case-insensitive, so the ordinal-ignore-case comparer is used.
function Test-WReparseWithinRoot {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$Path,
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$Root
    )
    if ($null -eq $Path -or $null -eq $Root) { return $false }
    if ([string]::IsNullOrWhiteSpace($Path) -or [string]::IsNullOrWhiteSpace($Root)) { return $false }

    $p = $null
    $r = $null
    try { $p = Get-WReparseCanonicalPath -Path $Path } catch { return $false }
    try { $r = Get-WReparseCanonicalPath -Path $Root } catch { return $false }
    if ([string]::IsNullOrEmpty($p) -or [string]::IsNullOrEmpty($r)) { return $false }

    if ([System.StringComparer]::OrdinalIgnoreCase.Equals($p, $r)) { return $true }

    $prefix = $r
    if (-not $prefix.EndsWith('\')) { $prefix = $prefix + '\' }
    if ($p.Length -le $prefix.Length) { return $false }
    return $p.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)
}

# Relative path of a scanned entry with respect to the scan root, using the
# Windows separator. The root itself yields '.'.
function Get-WReparseRelativePath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$FullPath,
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$Root
    )
    $p = [string]$FullPath
    $r = [string]$Root
    if ($null -eq $FullPath) { $p = '' }
    if ($null -eq $Root) { $r = '' }
    try { $p = Get-WReparseCanonicalPath -Path $p } catch { }
    try { $r = Get-WReparseCanonicalPath -Path $r } catch { }

    if ([string]::IsNullOrEmpty($p)) { return $script:WReparseRootRelativePath }
    if ([string]::IsNullOrEmpty($r)) { return $p }
    if ([System.StringComparer]::OrdinalIgnoreCase.Equals($p, $r)) { return $script:WReparseRootRelativePath }

    $prefix = $r
    if (-not $prefix.EndsWith('\')) { $prefix = $prefix + '\' }
    if (($p.Length -gt $prefix.Length) -and $p.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $p.Substring($prefix.Length)
    }
    return $p
}

# The reparse target stored on disk may be relative (contract 5.3). A relative
# target is resolved against the directory that CONTAINS the link, never against
# the process working directory and never against the scan root.
function Resolve-WReparseLinkTarget {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$LinkFullPath,
        [AllowNull()][AllowEmptyCollection()]$RawTarget
    )

    $target = ConvertTo-WReparseTargetString -RawTarget $RawTarget
    if ([string]::IsNullOrWhiteSpace($target)) { return $null }

    try {
        if ([System.IO.Path]::IsPathRooted($target)) {
            return Get-WReparseCanonicalPath -Path $target
        }

        if ([string]::IsNullOrWhiteSpace($LinkFullPath)) { return $null }
        $linkDirectory = [System.IO.Path]::GetDirectoryName($LinkFullPath)
        if ([string]::IsNullOrWhiteSpace($linkDirectory)) { return $null }

        $combined = [System.IO.Path]::Combine($linkDirectory, $target)
        return Get-WReparseCanonicalPath -Path $combined
    }
    catch {
        return $null
    }
}

# Stable ordering key comparison (contract 6): ordinal, case-insensitive first,
# with an ordinal case-sensitive tie-break so that two entries whose names
# differ only by case keep a deterministic position. Host culture is never
# consulted: 'Z' (U+005A) sorts before 'A' with a diaeresis (U+00C4) and before
# 'o' with a diaeresis (U+00F6).
function Compare-WReparsePath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$Left,
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$Right
    )
    $left = [string]$Left
    $right = [string]$Right
    if ($null -eq $Left) { $left = '' }
    if ($null -eq $Right) { $right = '' }

    $primary = [System.StringComparer]::OrdinalIgnoreCase.Compare($left, $right)
    if ($primary -ne 0) { return $primary }
    return [System.StringComparer]::Ordinal.Compare($left, $right)
}

# Compares two composite ordering keys element by element using the ordinal
# rules above. A missing element sorts before a present one.
function Compare-WReparseKeyList {
    [CmdletBinding()]
    param(
        [AllowNull()][AllowEmptyCollection()][string[]]$Left,
        [AllowNull()][AllowEmptyCollection()][string[]]$Right
    )
    $left = @($Left)
    $right = @($Right)
    $count = [System.Math]::Max($left.Count, $right.Count)
    for ($index = 0; $index -lt $count; $index++) {
        $leftValue = $null
        $rightValue = $null
        if ($index -lt $left.Count) { $leftValue = [string]$left[$index] }
        if ($index -lt $right.Count) { $rightValue = [string]$right[$index] }
        $result = Compare-WReparsePath -Left $leftValue -Right $rightValue
        if ($result -ne 0) { return $result }
    }
    return 0
}

# WReparse - directory walker
# Safe directory enumeration: reparse classification, containment, cycle and
# depth control. Part of the WReparse reference implementation.
#
# Everything in this file is internal: the module publishes only the six
# contract functions.

# Reads a member without triggering provider side effects and without throwing
# when the member is absent.
function Get-WReparseMemberValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()]$InputObject,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Name
    )
    if ($null -eq $InputObject) { return $null }
    $psObject = $InputObject.PSObject
    if ($null -eq $psObject) { return $null }
    $property = $psObject.Properties[$Name]
    if ($null -eq $property) { return $null }
    try { return $property.Value } catch { return $null }
}

# Maps the provider link type onto the contract vocabulary. Only entries whose
# file attributes carry FILE_ATTRIBUTE_REPARSE_POINT reach this function, so a
# hard link (which has a link type but no reparse attribute) is never mapped.
# Junction and SymbolicLink stay distinct.
function Get-WReparseKindFromLinkType {
    [CmdletBinding()]
    param([AllowNull()][AllowEmptyString()][string]$LinkType)
    if ([string]::IsNullOrWhiteSpace($LinkType)) { return $script:WReparseReparseKindUnknown }
    switch ($LinkType) {
        'SymbolicLink' { return $script:WReparseReparseKindSymbolicLink }
        'Junction' { return $script:WReparseReparseKindJunction }
        'MountPoint' { return $script:WReparseReparseKindMountPoint }
        default { return $script:WReparseReparseKindUnknown }
    }
}

# A reparse point is identified ONLY by FILE_ATTRIBUTE_REPARSE_POINT. A hard
# link reports LinkType 'HardLink' but has no reparse attribute and therefore is
# an ordinary file.
function Test-WReparseIsReparsePoint {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][AllowNull()]$Item)
    $attributes = Get-WReparseMemberValue -InputObject $Item -Name 'Attributes'
    if ($null -eq $attributes) { return $false }

    $value = $null
    if ($attributes -is [System.IO.FileAttributes]) {
        $value = [int]$attributes
    }
    else {
        $parsed = $attributes -as [System.IO.FileAttributes]
        if ($null -eq $parsed) { return $false }
        $value = [int]$parsed
    }

    $mask = [int][System.IO.FileAttributes]::ReparsePoint
    return (($value -band $mask) -eq $mask)
}

function Add-WReparseError {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$RelativePath,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Code,
        [Parameter(Mandatory = $true)][AllowEmptyString()][AllowNull()][string]$Message
    )
    [void]$State.Errors.Add((New-WReparseError -RelativePath $RelativePath -Code $Code -Message $Message))
}

# Ancestry test for cycle detection. Only the directories on the CURRENT branch
# are consulted, so two sibling links that point at the same target are not a
# cycle. Comparison is ordinal-ignore-case on canonical paths.
function Test-WReparseIsAncestor {
    [CmdletBinding()]
    param(
        [AllowNull()][AllowEmptyCollection()][string[]]$Ancestry,
        [AllowNull()][AllowEmptyString()][string]$Path
    )
    if ($null -eq $Ancestry) { return $false }
    if ([string]::IsNullOrEmpty($Path)) { return $false }
    foreach ($entry in @($Ancestry)) {
        if ($null -eq $entry) { continue }
        if ([string]::IsNullOrEmpty([string]$entry)) { continue }
        if ([System.StringComparer]::OrdinalIgnoreCase.Equals([string]$entry, $Path)) { return $true }
    }
    return $false
}

function Invoke-WReparseDirectoryWalk {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$RealDirectory,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$VirtualDirectory,
        [Parameter(Mandatory = $true)][int]$Depth,
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyCollection()][string[]]$Ancestry,
        [Parameter(Mandatory = $true)][hashtable]$State
    )

    $children = @()
    $enumerationErrors = $null
    try {
        $children = @(Get-ChildItem -LiteralPath $RealDirectory -Force -ErrorAction SilentlyContinue -ErrorVariable enumerationErrors)
    }
    catch {
        $children = @()
        $enumerationErrors = @($_)
    }

    # A failing directory never aborts the scan; it is reported and the rest of
    # the tree keeps producing records. Whatever could be enumerated is still
    # processed.
    if ($null -ne $enumerationErrors) {
        $errorList = @($enumerationErrors)
        if ($errorList.Count -gt 0) {
            $relative = Get-WReparseRelativePath -FullPath $VirtualDirectory -Root $State.Root
            $detail = [string]$errorList[0]
            Add-WReparseError -State $State -RelativePath $relative -Code 'access_denied' `
                -Message "Directory could not be enumerated: $detail"
        }
    }

    foreach ($child in $children) {
        if ($null -eq $child) { continue }

        $childDepth = $Depth + 1
        $realChild = [string](Get-WReparseMemberValue -InputObject $child -Name 'FullName')
        if ([string]::IsNullOrEmpty($realChild)) { continue }

        $leaf = [string](Get-WReparseMemberValue -InputObject $child -Name 'Name')
        if ([string]::IsNullOrEmpty($leaf)) { $leaf = [string][System.IO.Path]::GetFileName($realChild) }
        if ([string]::IsNullOrEmpty($leaf)) { continue }

        $virtualChild = Join-Path -Path $VirtualDirectory -ChildPath $leaf
        $relative = Get-WReparseRelativePath -FullPath $virtualChild -Root $State.Root

        if (Test-WReparseIsReparsePoint -Item $child) {
            $linkType = [string](Get-WReparseMemberValue -InputObject $child -Name 'LinkType')
            $rawTarget = ConvertTo-WReparseTargetString -RawTarget (Get-WReparseMemberValue -InputObject $child -Name 'Target')
            $resolved = Resolve-WReparseLinkTarget -LinkFullPath $realChild -RawTarget $rawTarget

            $inScope = $false
            if (-not [string]::IsNullOrEmpty($resolved)) {
                $inScope = Test-WReparseWithinRoot -Path $resolved -Root $State.Root
            }

            [void]$State.Records.Add((New-WReparseRecord -RelativePath $relative `
                -Kind $script:WReparseKindReparse `
                -ReparseKind (Get-WReparseKindFromLinkType -LinkType $linkType) `
                -Target $rawTarget -ResolvedTarget $resolved -InScope $inScope `
                -Depth $childDepth -Size 0))

            # Default: never enter a reparse target, only register the entry.
            # Without -Follow no cycle and no broken_target error may appear,
            # so the target is not even probed on disk.
            if (-not $State.Follow) {
                $State.Skipped = [int]$State.Skipped + 1
                continue
            }

            if ([string]::IsNullOrEmpty($resolved)) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'broken_target' `
                    -Message 'The reparse target could not be resolved.'
                continue
            }

            $targetExists = $false
            $targetIsContainer = $false
            try {
                $targetExists = [bool](Test-Path -LiteralPath $resolved -ErrorAction SilentlyContinue)
                if ($targetExists) {
                    $targetIsContainer = [bool](Test-Path -LiteralPath $resolved -PathType Container -ErrorAction SilentlyContinue)
                }
            }
            catch {
                $targetExists = $false
                $targetIsContainer = $false
            }

            if (-not $targetExists) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'broken_target' `
                    -Message 'The reparse target does not exist.'
                continue
            }

            # A link onto a file registers the link entry only: no children.
            if (-not $targetIsContainer) { continue }

            if (Test-WReparseIsAncestor -Ancestry $Ancestry -Path $resolved) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'cycle' `
                    -Message 'The reparse target is an ancestor of this branch.'
                continue
            }

            if ($childDepth -ge [int]$State.MaxDepth) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'too_deep' `
                    -Message "Depth limit of $([int]$State.MaxDepth) reached; not enumerating."
                continue
            }

            # Entries below the link are named after the LINK path, not after
            # the real target path.
            Invoke-WReparseDirectoryWalk -RealDirectory $resolved -VirtualDirectory $virtualChild `
                -Depth $childDepth -Ancestry (@($Ancestry) + [string]$resolved) -State $State
            continue
        }

        $isContainer = [bool](Get-WReparseMemberValue -InputObject $child -Name 'PSIsContainer')
        $size = [long]0
        if (-not $isContainer) {
            $length = Get-WReparseMemberValue -InputObject $child -Name 'Length'
            if ($null -ne $length) {
                try { $size = [long]$length } catch { $size = [long]0 }
            }
        }

        $kind = $script:WReparseKindFile
        if ($isContainer) { $kind = $script:WReparseKindDirectory }

        # InScope only carries meaning for reparse entries; ordinary files and
        # directories always report $false.
        [void]$State.Records.Add((New-WReparseRecord -RelativePath $relative -Kind $kind `
            -InScope $false -Depth $childDepth -Size $size))

        if ($isContainer) {
            if ($childDepth -ge [int]$State.MaxDepth) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'too_deep' `
                    -Message "Depth limit of $([int]$State.MaxDepth) reached; not enumerating."
                continue
            }
            $realChildCanonical = $realChild
            try { $realChildCanonical = Get-WReparseCanonicalPath -Path $realChild } catch { $realChildCanonical = $realChild }
            Invoke-WReparseDirectoryWalk -RealDirectory $realChildCanonical -VirtualDirectory $virtualChild `
                -Depth $childDepth -Ancestry (@($Ancestry) + [string]$realChildCanonical) -State $State
        }
    }
}

function Invoke-WReparseWalk {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$Root,
        [int]$MaxDepth = 32,
        [switch]$Follow
    )

    $effectiveMaxDepth = [int]$MaxDepth
    if ($effectiveMaxDepth -lt 0) { $effectiveMaxDepth = 0 }

    $state = @{
        Records  = New-Object System.Collections.ArrayList
        Errors   = New-Object System.Collections.ArrayList
        Skipped  = 0
        Root     = $null
        Follow   = [bool]$Follow
        MaxDepth = $effectiveMaxDepth
    }

    $canonicalRoot = $null
    try {
        $canonicalRoot = Get-WReparseCanonicalPath -Path $Root
    }
    catch {
        $state.Root = [string]$Root
        Add-WReparseError -State $state -RelativePath $script:WReparseRootRelativePath -Code 'invalid_argument' `
            -Message "Scan root could not be canonicalised: $([string]$Root)"
        return [pscustomobject]@{
            Root    = [string]$state.Root
            Records = $state.Records.ToArray()
            Errors  = $state.Errors.ToArray()
            Skipped = 0
        }
    }

    $state.Root = $canonicalRoot

    $rootExists = $false
    try { $rootExists = [bool](Test-Path -LiteralPath $canonicalRoot -ErrorAction SilentlyContinue) } catch { $rootExists = $false }
    if (-not $rootExists) {
        Add-WReparseError -State $state -RelativePath $script:WReparseRootRelativePath -Code 'not_found' `
            -Message "Scan root does not exist: $canonicalRoot"
        return [pscustomobject]@{
            Root    = [string]$canonicalRoot
            Records = $state.Records.ToArray()
            Errors  = $state.Errors.ToArray()
            Skipped = 0
        }
    }

    $rootIsContainer = $false
    try { $rootIsContainer = [bool](Test-Path -LiteralPath $canonicalRoot -PathType Container -ErrorAction SilentlyContinue) } catch { $rootIsContainer = $false }
    if (-not $rootIsContainer) {
        Add-WReparseError -State $state -RelativePath $script:WReparseRootRelativePath -Code 'structure' `
            -Message "Scan root is not a directory: $canonicalRoot"
        return [pscustomobject]@{
            Root    = [string]$canonicalRoot
            Records = $state.Records.ToArray()
            Errors  = $state.Errors.ToArray()
            Skipped = 0
        }
    }

    Invoke-WReparseDirectoryWalk -RealDirectory $canonicalRoot -VirtualDirectory $canonicalRoot `
        -Depth 0 -Ancestry @($canonicalRoot) -State $state

    return [pscustomobject]@{
        Root    = [string]$canonicalRoot
        Records = $state.Records.ToArray()
        Errors  = $state.Errors.ToArray()
        Skipped = [int]$state.Skipped
    }
}

# WReparse - report assembly
# Deterministic ordering, statistics and serialisation.
# Part of the WReparse reference implementation.
#
# Only Get-WReparseReport and ConvertTo-WReparseJson belong to the public
# surface; the sorting and statistics helpers are internal.

# Ordering keys. Records are keyed by RelativePath; errors are keyed by
# RelativePath then Code (then Message, purely to keep equal keys stable).
function Get-WReparseRecordSortKey {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][AllowNull()]$Item)
    return [string[]]@([string](Get-WReparseMemberValue -InputObject $Item -Name 'RelativePath'))
}

function Get-WReparseErrorSortKey {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][AllowNull()]$Item)
    return [string[]]@(
        [string](Get-WReparseMemberValue -InputObject $Item -Name 'RelativePath'),
        [string](Get-WReparseMemberValue -InputObject $Item -Name 'Code'),
        [string](Get-WReparseMemberValue -InputObject $Item -Name 'Message')
    )
}

# Stable merge sort so the report never depends on the enumerator order or on
# the host culture. Sort-Object is deliberately not used: its default string
# comparison is culture-aware and would order non-ASCII names differently on
# different hosts (for example it puts 'A' with a diaeresis before 'Z', while
# the ordinal comparison required by the contract puts 'Z' first).
function Sort-WReparseStable {
    [CmdletBinding()]
    param(
        [AllowNull()][AllowEmptyCollection()][object[]]$Items,
        [Parameter(Mandatory = $true)][scriptblock]$KeySelector
    )

    $items = @($Items)
    $count = $items.Count
    if ($count -eq 0) { return @() }
    if ($count -eq 1) { return @($items[0]) }

    # Decorate once: keys are computed a single time per item.
    $keys = New-Object 'object[]' $count
    for ($index = 0; $index -lt $count; $index++) {
        $keys[$index] = [string[]]@(& $KeySelector $items[$index])
    }

    $source = New-Object 'int[]' $count
    for ($index = 0; $index -lt $count; $index++) { $source[$index] = $index }
    $buffer = New-Object 'int[]' $count

    $width = 1
    while ($width -lt $count) {
        for ($start = 0; $start -lt $count; $start += (2 * $width)) {
            $middle = $start + $width
            if ($middle -gt $count) { $middle = $count }
            $end = $start + (2 * $width)
            if ($end -gt $count) { $end = $count }

            $left = $start
            $right = $middle
            $write = $start
            while (($left -lt $middle) -and ($right -lt $end)) {
                $comparison = Compare-WReparseKeyList -Left ([string[]]$keys[$source[$left]]) -Right ([string[]]$keys[$source[$right]])
                if ($comparison -le 0) {
                    $buffer[$write] = $source[$left]
                    $left++
                }
                else {
                    $buffer[$write] = $source[$right]
                    $right++
                }
                $write++
            }
            while ($left -lt $middle) { $buffer[$write] = $source[$left]; $left++; $write++ }
            while ($right -lt $end) { $buffer[$write] = $source[$right]; $right++; $write++ }
        }

        $swap = $source
        $source = $buffer
        $buffer = $swap
        $width = $width * 2
    }

    $sorted = New-Object 'object[]' $count
    for ($index = 0; $index -lt $count; $index++) { $sorted[$index] = $items[$source[$index]] }
    return $sorted
}

# The three category counters are mutually exclusive and mirror the records.
function Get-WReparseStats {
    [CmdletBinding()]
    param(
        [AllowNull()][AllowEmptyCollection()][object[]]$Records,
        [int]$Skipped = 0,
        [int]$ErrorCount = 0
    )
    $directories = 0
    $files = 0
    $reparse = 0
    foreach ($record in @($Records)) {
        if ($null -eq $record) { continue }
        $kind = [string](Get-WReparseMemberValue -InputObject $record -Name 'Kind')
        if ($kind -eq $script:WReparseKindReparse) { $reparse++ }
        elseif ($kind -eq $script:WReparseKindDirectory) { $directories++ }
        elseif ($kind -eq $script:WReparseKindFile) { $files++ }
    }
    return New-WReparseStats -Directories $directories -Files $files -ReparsePoints $reparse `
        -Skipped $Skipped -Errors $ErrorCount
}

function Get-WReparseReport {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()][AllowEmptyString()][string]$Root,
        [int]$MaxDepth = 32,
        [switch]$Follow
    )

    $effectiveMaxDepth = [int]$MaxDepth
    if ($effectiveMaxDepth -lt 0) { $effectiveMaxDepth = 0 }

    $walk = Invoke-WReparseWalk -Root $Root -MaxDepth $effectiveMaxDepth -Follow:$Follow

    $records = @(Sort-WReparseStable -Items @($walk.Records) -KeySelector { param($item) Get-WReparseRecordSortKey -Item $item })
    $errors = @(Sort-WReparseStable -Items @($walk.Errors) -KeySelector { param($item) Get-WReparseErrorSortKey -Item $item })

    $stats = Get-WReparseStats -Records $records -Skipped ([int]$walk.Skipped) -ErrorCount $errors.Count

    $reportRoot = [string]$walk.Root
    if ([string]::IsNullOrEmpty($reportRoot)) {
        try { $reportRoot = Get-WReparseCanonicalPath -Path $Root } catch { $reportRoot = [string]$Root }
    }

    return New-WReparseReport -Root $reportRoot -Records $records -Errors $errors -Stats $stats
}

function ConvertTo-WReparseJson {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()]$Report
    )
    return (ConvertTo-Json -InputObject $Report -Depth 12)
}

